// `ros init` — create a deploy.yaml in the current project.

import { existsSync } from "node:fs"
import { writeFile } from "node:fs/promises"
import { resolve } from "node:path"
import type { Command } from "../types.ts"
import { success, warn, info } from "../ui.ts"

const TEMPLATE = `# @anteros/cli configuration
# Generated by \`ros init\`

version: "1"
name: "my-app"

deploy:
  tag: v0.1.0
  strategy: rolling

ssh:
  port: 22
  timeout: 60

environments:
  test:
    servers:
      - root@192.168.10.11
  staging:
    servers:
      - root@192.168.20.11
  production:
    servers:
      - root@192.168.30.11

pods:
  api:
    type: api
    driver: docker
    instances: 1
    containers:
      - name: api
        image: ghcr.io/myorg/api
        tag: v0.1.0
        ports: ["3001:3001"]
        healthcheck: /healthz
        restart: unless-stopped

proxy:
  routes:
    - domain: api.example.com
      upstream_port: 3001
      tls: auto
`

export const init: Command = async ({ opts, log, warn }) => {
  const target = resolve(process.cwd(), "deploy.yaml")
  if (existsSync(target) && !opts.force) {
    warn(`deploy.yaml already exists at ${target}. Use --force to overwrite.`)
    return
  }
  await writeFile(target, TEMPLATE, "utf8")
  success(`Created ${target}`)
  info("Edit it to match your project, then run `ros deploy --env test`.")
}
